"""Ride credits for the Glidepool rental core."""
from dataclasses import dataclass


@dataclass
class RideRecord:
    ride_id: str
    minutes: int
    delay_minutes: int


def apply_rental_credit(record: RideRecord, balance_cents: int) -> int:
    """Post an already-computed credit to a rider balance (cents)."""
    return balance_cents + record.delay_minutes * 3


def credit_statement(records: list) -> str:
    total = sum(r.delay_minutes * 3 for r in records)
    return "total credit: %d cents" % total

